1	//! Profile 2: opaque service evidence and authoritative admission proofs.
2	//!
3	//! This is an owner-side storage API, not an RPC authorization boundary. Grants
4	//! and archive bindings must come from trusted configuration. The legacy Ledger
5	//! cannot open this profile. Writable opens require every retained payload.
6	use super::*;
7	use crate::{
8	    evidence_attestation::{self as proof, Context, Frontier, Purpose, Verified},
9	    evidence_service::{self as service, Failure, Grant, SignedRequest},
10	    sign::Identity,
11	};
12	
13	pub(crate) const SCHEMA: &str = "
14	CREATE TABLE archive_identity(
15	 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
16	 archive BLOB NOT NULL CHECK(length(archive)=32),
17	 scope BLOB NOT NULL CHECK(length(scope)=32), issuer TEXT NOT NULL);
18	CREATE TABLE attestations(
19	 sequence INTEGER PRIMARY KEY REFERENCES commits(sequence),
20	 envelope BLOB NOT NULL CHECK(length(envelope)>0 AND length(envelope)<=16384));
21	PRAGMA user_version=2;
22	";
23	
24	#[derive(Debug, Clone, PartialEq, Eq)]
25	pub struct Binding {
26	    pub archive: [u8; 32],
27	    pub scope: [u8; 32],
28	    pub issuer: String,
29	}
30	impl Binding {
31	    fn context(&self) -> Context<'_> {
32	        Context {
33	            archive: self.archive,
34	            scope: self.scope,
35	            issuer: &self.issuer,
36	        }
37	    }
38	    fn validate(&self) -> Result<()> {
39	        // The service author codec rejects unsupported/noncanonical keys. The
40	        // attestation codec further checks the exact static P-256 spelling.
41	        if !(56..=80).contains(&self.issuer.len())
42	            || !self.issuer.starts_with("did:key:z")
43	            || !self.issuer.is_ascii()
44	        {
45	            return Err(Error::Invalid("archive issuer"));
46	        }
47	        service::author(&self.issuer).map_err(|_| Error::Invalid("archive issuer"))?;
48	        let (algorithm, key) = atrium_crypto::did::parse_did_key(&self.issuer)
49	            .map_err(|_| Error::Invalid("archive issuer"))?;
50	        if algorithm != atrium_crypto::Algorithm::P256
51	            || atrium_crypto::did::format_did_key(algorithm, &key)
52	                .ok()
53	                .as_ref()
54	                != Some(&self.issuer)
55	        {
56	            return Err(Error::Invalid("archive requires canonical P-256 issuer"));
57	        }
58	        Ok(())
59	    }
60	}
61	
62	pub(super) fn initialize(tx: &rusqlite::Transaction<'_>, binding: &Binding) -> Result<()> {
63	    binding.validate()?;
64	    // surface-write: evidence-proof-sqlite:archive_identity,evidence-proof-sqlite:attestations
65	    crate::persistence::initialize_evidence_proofs(
66	        crate::persistence::SurfaceWrite::EvidenceAttestation,
67	        tx,
68	        &binding.archive,
69	        &binding.scope,
70	        &binding.issuer,
71	    )?;
72	    Ok(())
73	}
74	
75	pub struct Archive {
76	    ledger: Ledger,
77	    binding: Binding,
78	}
79	#[derive(Debug)]
80	pub struct Admission {
81	    pub record: Committed,
82	    pub attestation: Verified,
83	}
84	
85	fn corrupt(message: &str) -> Error {
86	    Error::Corrupt(message.into())
87	}
88	fn check_binding(conn: &Connection, binding: &Binding) -> Result<()> {
89	    let count: i64 = conn.query_row("SELECT count(*) FROM archive_identity", [], |r| r.get(0))?;
90	    let actual: (Vec<u8>, Vec<u8>, String) = conn.query_row(
91	        "SELECT archive,scope,issuer FROM archive_identity WHERE singleton=1",
92	        [],
93	        |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
94	    )?;
95	    if count != 1
96	        || actual.0 != binding.archive
97	        || actual.1 != binding.scope
98	        || actual.2 != binding.issuer
99	    {
100	        return Err(corrupt(
101	            "archive identity does not match owner configuration",
102	        ));
103	    }
104	    Ok(())
105	}
106	fn envelope(conn: &Connection, sequence: u64) -> Result<Vec<u8>> {
107	    let row: Option<(i64, Vec<u8>)> = conn
108	        .query_row(
109	            "SELECT length(envelope),substr(envelope,1,16384) FROM attestations WHERE sequence=?",
110	            [i64::try_from(sequence).map_err(|_| Error::Invalid("sequence overflow"))?],
111	            |r| Ok((r.get(0)?, r.get(1)?)),
112	        )
113	        .optional()?;
114	    let (len, bytes) = row.ok_or_else(|| corrupt("missing attestation"))?;
115	    if !(1..=proof::MAX_ENVELOPE_BYTES as i64).contains(&len) {
116	        return Err(corrupt("attestation length"));
117	    }
118	    Ok(bytes)
119	}
120	fn record(conn: &Connection, sequence: u64) -> Result<Committed> {
121	    let mut stmt = conn.prepare(&format!("{RAW_COMMITS} WHERE sequence=?"))?;
122	    let mut rows =
123	        stmt.query([i64::try_from(sequence).map_err(|_| Error::Invalid("sequence overflow"))?])?;
124	    raw_commit(rows.next()?.ok_or(Error::MissingCommit(sequence))?)
125	}
126	fn retained(conn: &Connection, record: &Committed, binding: &Binding) -> Result<SignedRequest> {
127	    let es: Vec<_> = entries(&record.manifest).collect();
128	    if es.len() != 1 {
129	        return Err(corrupt("service manifest entries"));
130	    }
131	    let id = cid(&es[0]["ciphertext"]);
132	    let row: Option<(i64, Vec<u8>)> = conn
133	        .query_row(
134	            "SELECT length(bytes),substr(bytes,1,2101248) FROM objects WHERE cid=?",
135	            [&id],
136	            |r| Ok((r.get(0)?, r.get(1)?)),
137	        )
138	        .optional()?;
139	    let (len, bytes) = row.ok_or_else(|| Error::Missing(id.clone()))?;
140	    if !(1..=service::MAX_REQUEST as i64).contains(&len)
141	        || bytes.len() as i64 != len
142	        || ciphertext_cid(&bytes).to_string() != id
143	    {
144	        return Err(corrupt("retained signed request"));
145	    }
146	    let signed = service::verify_retained_request(record, &bytes)
147	        .map_err(|_| corrupt("retained request binding"))?;
148	    if signed.request.scope != service::hex(&binding.scope) {
149	        return Err(corrupt("retained request scope"));
150	    }
151	    Ok(signed)
152	}
153	
154	// Caller owns a transaction. Constant working memory; currently a full scan.
155	// `through` excludes a new, not-yet-attested row inside admission's transaction.
156	fn audit_prefix(
157	    conn: &Connection,
158	    binding: &Binding,
159	    through: u64,
160	    target: Option<&Cid>,
161	) -> Result<(Frontier, Option<Verified>)> {
162	    check_binding(conn, binding)?;
163	    let count: i64 = conn.query_row("SELECT count(*) FROM attestations", [], |r| r.get(0))?;
164	    if u64::try_from(count).ok() != Some(through) {
165	        return Err(corrupt("attestation cardinality"));
166	    }
167	    let mut frontier = Frontier::default();
168	    let mut selected = None;
169	    let mut stmt = conn.prepare(&format!(
170	        "{RAW_COMMITS} WHERE sequence<=? ORDER BY sequence"
171	    ))?;
172	    let mut rows =
173	        stmt.query([i64::try_from(through).map_err(|_| Error::Invalid("sequence overflow"))?])?;
174	    while let Some(row) = rows.next()? {
175	        let record = raw_commit(row)?;
176	        if record.sequence != frontier.through + 1 {
177	            return Err(corrupt("noncontiguous attestation chain"));
178	        }
179	        let verified = proof::verify(
180	            &envelope(conn, record.sequence)?,
181	            &binding.context(),
182	            &record.manifest,
183	            &record.receipt,
184	            &frontier,
185	        )
186	        .map_err(|_| corrupt("invalid attestation chain"))?;
187	        let signed = retained(conn, &record, binding)?;
188	        match verified.purpose() {
189	            Purpose::Admitted => {
190	                if signed.request.audience != binding.issuer {
191	                    return Err(corrupt("admitted request audience"));
192	                }
193	            }
194	            Purpose::RetainedVerified => {
195	                return Err(corrupt("retained-verified prefix requires copy profile"));
196	            }
197	        }
198	        frontier = verified.frontier().clone();
199	        if target == Some(record.manifest.cid()) {
200	            selected = Some(verified);
201	        }
202	    }
203	    if frontier.through != through {
204	        return Err(corrupt("attestation chain length"));
205	    }
206	    Ok((frontier, selected))
207	}
208	impl Archive {
209	    pub fn create(root: &Path, binding: Binding) -> Result<Self> {
210	        Self::create_observed(root, binding, &mut |_| {})
211	    }
212	    /// Fault harness only; callbacks do not establish durability.
213	    pub fn create_observed(
214	        root: &Path,
215	        binding: Binding,
216	        observe: &mut dyn FnMut(InitializationBoundary),
217	    ) -> Result<Self> {
218	        binding.validate()?;
219	        let ledger = Ledger::create_profile(root, observe, Some(&binding))?;
220	        ledger.conn.set_limit(
221	            rusqlite::limits::Limit::SQLITE_LIMIT_LENGTH,
222	            RECOVERY_SQLITE_LENGTH_LIMIT,
223	        )?;
224	        Ok(Self { ledger, binding })
225	    }
226	    pub fn open(root: &Path, binding: Binding) -> Result<Self> {
227	        binding.validate()?;
228	        let path = root.join("archive.sqlite");
229	        private_file(&path)?;
230	        let conn = Connection::open_with_flags(&path, OpenFlags::SQLITE_OPEN_READ_WRITE)?;
231	        conn.set_limit(
232	            rusqlite::limits::Limit::SQLITE_LIMIT_LENGTH,
233	            RECOVERY_SQLITE_LENGTH_LIMIT,
234	        )?;
235	        conn.busy_timeout(Duration::from_secs(5))?;
236	        let archive = Self {
237	            ledger: Ledger { conn },
238	            binding,
239	        };
240	        archive.ledger.check_profile(2)?;
241	        archive.ledger.check_write_profile(true)?;
242	        archive.verify()?;
243	        configure(&archive.ledger.conn)?;
244	        Ok(archive)
245	    }
246	    /// Explicit owner opt-in for interrupted creation. Empty foreign files are
247	    /// indistinguishable from interrupted output; no existing profile is converted.
248	    pub fn resume_initialization(root: &Path, binding: Binding) -> Result<Self> {
249	        binding.validate()?;
250	        let path = root.join("archive.sqlite");
251	        private_file(&path)?;
252	        let conn = Connection::open_with_flags(&path, OpenFlags::SQLITE_OPEN_READ_WRITE)?;
253	        let app: i64 = conn.query_row("PRAGMA application_id", [], |r| r.get(0))?;
254	        let version: i64 = conn.query_row("PRAGMA user_version", [], |r| r.get(0))?;
255	        drop(conn);
256	        let archive = if app == APPLICATION_ID && version == 2 {
257	            Self::open(root, binding)?
258	        } else {
259	            let ledger = Ledger::initialize_empty(root, &path, &mut |_| {}, Some(&binding))?;
260	            ledger.conn.set_limit(
261	                rusqlite::limits::Limit::SQLITE_LIMIT_LENGTH,
262	                RECOVERY_SQLITE_LENGTH_LIMIT,
263	            )?;
264	            Self { ledger, binding }
265	        };
266	        std::fs::File::open(root)?.sync_all()?;
267	        std::fs::File::open(parent_directory(root))?.sync_all()?;
268	        Ok(archive)
269	    }
270	    /// Full standalone backup. A failure may leave an incomplete or complete
271	    /// output; use a fresh destination, never overwrite or promote automatically.
272	    pub fn backup(&self, destination: &Path) -> Result<Verification> {
273	        self.backup_observed(destination, &mut |_| {})
274	    }
275	    pub fn backup_observed(
276	        &self,
277	        destination: &Path,
278	        observe: &mut dyn FnMut(BackupBoundary),
279	    ) -> Result<Verification> {
280	        let destination = self.ledger.backup_copy(destination, observe)?;
281	        Self::verify_file(&destination, self.binding.clone())
282	    }
283	    /// Full audit of a standalone profile-2 file against owner configuration.
284	    /// Read-only SQLite can initialize its declared WAL/SHM coordination files.
285	    pub fn verify_file(path: &Path, binding: Binding) -> Result<Verification> {
286	        let reader = Recovery::open(path, binding)?;
287	        reader.reader.ledger.check_write_profile(true)?;
288	        let base = reader.reader.ledger.verify_contents()?;
289	        verify_contents(&reader.reader.ledger, &reader.binding, &base)?;
290	        Ok(base)
291	    }
292	    pub fn binding(&self) -> &Binding {
293	        &self.binding
294	    }
295	    pub fn verify(&self) -> Result<Frontier> {
296	        self.verify_for(None).map(|(frontier, _)| frontier)
297	    }
298	    fn verify_for(&self, target: Option<&Cid>) -> Result<(Frontier, Option<Verified>)> {
299	        let tx = self.ledger.conn.unchecked_transaction()?;
300	        let base = self.ledger.verify_contents()?;
301	        let (frontier, selected) = audit_prefix(&tx, &self.binding, base.snapshot.through, target)?;
302	        if frontier.manifest != base.snapshot.tip {
303	            return Err(corrupt("attestation tip"));
304	        }
305	        tx.commit()?;
306	        Ok((frontier, selected))
307	    }
308	    /// Owner-side admission. The caller supplies a current trusted grant; remote
309	    /// callers must never be allowed to supply or choose this grant themselves.
310	    pub fn admit(
311	        &mut self,
312	        bytes: &[u8],
313	        signer: &Identity,
314	        grant: &Grant,
315	        now: u64,
316	    ) -> std::result::Result<Admission, Failure> {
317	        self.admit_observed(bytes, signer, grant, now, &mut |_| {})
318	    }
319	    /// Fault harness only: callbacks cannot establish durability.
320	    pub fn admit_observed(
321	        &mut self,
322	        bytes: &[u8],
323	        signer: &Identity,
324	        grant: &Grant,
325	        now: u64,
326	        observe: &mut dyn FnMut(Boundary),
327	    ) -> std::result::Result<Admission, Failure> {
328	        let signed = SignedRequest::decode(bytes)?;
329	        if !grant.append
330	            || grant.principal != signed.request.principal
331	            || signed.request.scope != service::hex(&self.binding.scope)
332	            || signed.request.audience != self.binding.issuer
333	            || signer.did().as_str() != self.binding.issuer
334	        {
335	            return Err(Failure::AccessLimited);
336	        }
337	        let manifest = service::append_manifest(bytes)?;
338	        let receipt = service::receipt(&manifest, &self.binding.issuer, now)?;
339	        let (previous, duplicate_proof) = self.verify_for(Some(manifest.cid()))?;
340	        self.ledger.stage_observed(bytes, observe)?;
341	        let expected = Snapshot {
342	            through: previous.through,
343	            tip: previous.manifest.clone(),
344	        };
345	        let binding = &self.binding;
346	        let mut result = None;
347	        let mut hook = |tx: &rusqlite::Transaction<'_>,
348	                        row: &Committed,
349	                        observe: &mut dyn FnMut(Boundary)|
350	         -> Result<()> {
351	            // All archive mutations through this API append. Recheck both tips
352	            // and proof cardinality under the immediate writer transaction; a
353	            // raw append or same-height replacement cannot cross this fence.
354	            check_binding(tx, binding)?;
355	            let count: i64 = tx.query_row("SELECT count(*) FROM attestations", [], |r| r.get(0))?;
356	            if u64::try_from(count).ok() != Some(previous.through) {
357	                return Err(Error::Conflict("attestation audit frontier"));
358	            }
359	            if previous.through > 0 {
360	                let tip = record(tx, previous.through)?;
361	                proof::verify_at(
362	                    &envelope(tx, previous.through)?,
363	                    &binding.context(),
364	                    &tip.manifest,
365	                    &tip.receipt,
366	                    &previous,
367	                )
368	                .map_err(|_| Error::Conflict("attestation audit frontier"))?;
369	            }
370	            let verified = if row.duplicate {
371	                let old = duplicate_proof
372	                    .as_ref()
373	                    .ok_or_else(|| corrupt("unaudited retry"))?;
374	                if old.frontier().through != row.sequence
375	                    || old.frontier().manifest.as_ref() != Some(row.manifest.cid())
376	                    || envelope(tx, row.sequence)? != old.bytes()
377	                {
378	                    return Err(Error::Conflict("retry proof changed"));
379	                }
380	                // Recheck exact receipt binding against the previously verified proof.
381	                proof::verify_at(
382	                    old.bytes(),
383	                    &binding.context(),
384	                    &row.manifest,
385	                    &row.receipt,
386	                    old.frontier(),
387	                )
388	                .map_err(|_| Error::Conflict("retry receipt changed"))?;
389	                if old.purpose() != Purpose::Admitted {
390	                    return Err(Error::Conflict(
391	                        "imported retry requires explicit confirmation",
392	                    ));
393	                }
394	                old.clone()
395	            } else {
396	                if row.sequence != previous.through + 1 {
397	                    return Err(corrupt("new attestation sequence"));
398	                }
399	                let proof = proof::issue(
400	                    signer,
401	                    &binding.context(),
402	                    &row.manifest,
403	                    &row.receipt,
404	                    &previous,
405	                    Purpose::Admitted,
406	                    now.checked_mul(1000).ok_or(Error::Invalid("timestamp"))?,
407	                )?;
408	                observe(Boundary::AttestationSigned);
409	                // surface-write: evidence-proof-sqlite:attestations
410	                crate::persistence::insert_evidence_proof(
411	                    crate::persistence::SurfaceWrite::EvidenceAttestation,
412	                    tx,
413	                    i64::try_from(row.sequence).map_err(|_| Error::Invalid("sequence overflow"))?,
414	                    proof.bytes(),
415	                )?;
416	                observe(Boundary::AttestationInserted);
417	                proof
418	            };
419	            result = Some(verified);
420	            Ok(())
421	        };
422	        let record = self.ledger.commit_inner(
423	            manifest.bytes(),
424	            receipt.bytes(),
425	            observe,
426	            true,
427	            Some(&expected),
428	            Some(&mut hook),
429	        )?;
430	        Ok(Admission {
431	            record,
432	            attestation: result.ok_or(Failure::Corrupt)?,
433	        })
434	    }
435	}
