437	/// Read-only pinned source for a full proof-preserving rebuild. Opening does not
438	/// certify raw contents; successful rebuild verifies all metadata, proofs and
439	/// payloads. No degraded or metadata-only success is returned by this API.
440	pub struct Recovery {
441	    reader: RecoveryReader,
442	    binding: Binding,
443	}
444	impl Recovery {
445	    pub fn open(path: &Path, binding: Binding) -> Result<Self> {
446	        binding.validate()?;
