463	pub(super) fn check_copy_source(conn: &Connection, binding: &Binding, through: u64) -> Result<()> {
464	    check_binding(conn, binding)?;
465	    let count: i64 = conn.query_row("SELECT count(*) FROM attestations", [], |r| r.get(0))?;
466	    if u64::try_from(count).ok() != Some(through) {
