+    let mut bytes = std::fs::read(&active).unwrap();
+    let offset = (root_page as usize - 1) * 4096;
+    bytes[offset..offset + 12].fill(0xff);
+    std::fs::write(&active, &bytes).unwrap();
+    let before = sha(&active);
